public class Solution {
    static final long MOD = 1_000_000_007L;

    // O(log exp) de tempo, O(1) de memória.
    static long modPow(long base, long exp, long mod) {
        if (exp < 0) throw new IllegalArgumentException("expoente negativo");
        if (mod <= 0) throw new IllegalArgumentException("módulo deve ser positivo");
        long resultado = 1 % mod;
        base %= mod;
        if (base < 0) base += mod;
        while (exp > 0) {
            if ((exp & 1) == 1) resultado = resultado * base % mod;
            base = base * base % mod;
            exp >>= 1;
        }
        return resultado;
    }

    // Pré-cálculo O(max); consultas O(1). Memória O(max).
    static class Combinatoria {
        private final long[] fat;
        private final long[] invFat;

        Combinatoria(int max) {
            if (max < 0) throw new IllegalArgumentException("max negativo");
            fat = new long[max + 1];
            invFat = new long[max + 1];
            fat[0] = 1;
            for (int i = 1; i <= max; i++) fat[i] = fat[i - 1] * i % MOD;
            invFat[max] = modPow(fat[max], MOD - 2, MOD); // Fermat: MOD é primo
            for (int i = max; i > 0; i--) invFat[i - 1] = invFat[i] * i % MOD;
        }

        long c(int n, int k) {
            if (n < 0 || n >= fat.length) throw new IllegalArgumentException("n fora do pré-cálculo: " + n);
            if (k < 0 || k > n) return 0;
            return fat[n] * invFat[k] % MOD * invFat[n - k] % MOD;
        }

        long caminhosNaGrade(int m, int n) {
            if (m < 1 || n < 1) throw new IllegalArgumentException("grade inválida");
            return c(m + n - 2, m - 1);
        }
    }
}

