import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void modPowBasico() {
        assertEquals(1024, Solution.modPow(2, 10, Solution.MOD));
        assertEquals(1, Solution.modPow(5, 0, Solution.MOD));
        assertEquals(0, Solution.modPow(5, 0, 1));
    }

    @Test void modPowFermatEExpoenteEnorme() {
        assertEquals(1, Solution.modPow(3, Solution.MOD - 1, Solution.MOD));
        // 2^(10^18) mod 13: o ciclo de 2 módulo 13 tem período 12; 10^18 % 12 == 4 -> 16 % 13 == 3
        assertEquals(3, Solution.modPow(2, 1_000_000_000_000_000_000L, 13));
    }

    @Test void modPowBaseNegativa() {
        assertEquals(6, Solution.modPow(-2, 3, 7));
        assertEquals(4, Solution.modPow(-2, 2, 7));
    }

    @Test void modPowValidacao() {
        assertThrows(IllegalArgumentException.class, () -> Solution.modPow(2, -1, 7));
        assertThrows(IllegalArgumentException.class, () -> Solution.modPow(2, 3, 0));
    }

    @Test void binomiaisPequenos() {
        var comb = new Solution.Combinatoria(20);
        assertEquals(10, comb.c(5, 2));
        assertEquals(1, comb.c(7, 0));
        assertEquals(1, comb.c(7, 7));
        assertEquals(184756, comb.c(20, 10));
        assertEquals(0, comb.c(5, 6));
        assertEquals(0, comb.c(5, -1));
    }

    @Test void binomialGrandeModular() {
        var comb = new Solution.Combinatoria(1_000_000);
        // C(10^6, 1) e simetria
        assertEquals(1_000_000, comb.c(1_000_000, 1));
        assertEquals(comb.c(1_000_000, 300_000), comb.c(1_000_000, 700_000));
        // Pascal: C(n, k) = C(n-1, k-1) + C(n-1, k)
        long esquerda = comb.c(999_999, 41);
        long direita = comb.c(999_999, 42);
        assertEquals((esquerda + direita) % Solution.MOD, comb.c(1_000_000, 42));
    }

    @Test void caminhos() {
        var comb = new Solution.Combinatoria(200_000);
        assertEquals(28, comb.caminhosNaGrade(3, 7));
        assertEquals(1, comb.caminhosNaGrade(1, 1));
        assertEquals(1, comb.caminhosNaGrade(1, 50));
        assertEquals(comb.c(199_998, 99_999), comb.caminhosNaGrade(100_000, 100_000));
    }

    @Test void validacaoCombinatoria() {
        var comb = new Solution.Combinatoria(10);
        assertThrows(IllegalArgumentException.class, () -> comb.c(11, 2));
        assertThrows(IllegalArgumentException.class, () -> comb.c(-1, 0));
        assertThrows(IllegalArgumentException.class, () -> comb.caminhosNaGrade(0, 3));
    }
}
